import { AdminNav } from "@/components/admin/admin-nav"; import { requireAdmin } from "@/lib/admin/authorization"; import { listAdminMedia } from "@/lib/admin/content"; import { getPreferences } from "@/lib/i18n/get-translations"; import { uploadMediaAction } from "../actions";
export default async function Page({searchParams}:{searchParams:Promise<Record<string,string|undefined>>}){const q=await searchParams,actor=await requireAdmin("MEDIA_READ"),prefs=await getPreferences(actor.id),d=await listAdminMedia(Number(q.page)||1);return <main className="min-h-screen bg-slate-50 px-4 py-6"><div className="mx-auto max-w-6xl"><AdminNav locale={prefs.interfaceLanguage}/><h1 className="mt-8 text-3xl font-black">Media</h1>{q.error&&<p role="alert" className="mt-4 rounded-lg bg-red-100 p-3">Upload thất bại: {q.error}</p>}<form action={uploadMediaAction} className="mt-5 flex flex-wrap items-end gap-3 rounded-2xl border bg-white p-5"><label className="font-semibold">Loại<select name="kind" className="mt-1 block rounded-lg border p-2"><option>AUDIO</option><option>IMAGE</option></select></label><label className="font-semibold">Tệp riêng tư<input required name="file" type="file" accept="audio/mpeg,image/jpeg,image/png,image/webp" className="mt-1 block rounded-lg border p-2"/></label><button className="rounded-lg bg-teal-700 px-4 py-2 font-bold text-white">Upload media</button></form><div className="mt-5 overflow-x-auto rounded-2xl border bg-white"><table className="w-full min-w-[800px] text-left"><thead><tr className="border-b bg-slate-100"><th className="p-3">ID</th><th>Loại</th><th>Trạng thái</th><th>Kích thước</th><th>Tham chiếu</th><th>Ngày tạo</th><th>Preview</th></tr></thead><tbody>{d.rows.map(r=><tr key={r.id} className="border-b"><td className="p-3 font-mono text-xs">{r.id}</td><td>{r.kind}<small className="block">{r.mimeType}</small></td><td>{r.status}</td><td>{Math.ceil(r.byteSize/1024)} KB</td><td>{r.references} {r.publishedReferences>0?"(published/historical)":r.references?"(draft)":"(unused)"}</td><td>{r.createdAt.toLocaleString()}</td><td>{r.status==="READY"&&<a className="font-bold text-teal-700" target="_blank" href={`/admin/content/media/${r.id}/preview`}>Mở</a>}</td></tr>)}</tbody></table></div><p className="mt-4">Trang {d.page} · {d.total} assets</p></div></main>}
